# frozen_string_literal: true

module RuboCop
  module Cop
    module Lint
      # Looks for references of Regexp captures that are out of range
      # and thus always returns nil.
      #
      # @safety
      #   This cop is unsafe because it is naive in how it determines what
      #   references are available based on the last encountered regexp, but
      #   it cannot handle some cases, such as conditional regexp matches, which
      #   leads to false positives, such as:
      #
      #   [source,ruby]
      #   ----
      #   foo ? /(c)(b)/ =~ str : /(b)/ =~ str
      #   do_something if $2
      #   # $2 is defined for the first condition but not the second, however
      #   # the cop will mark this as an offense.
      #   ----
      #
      #   This might be a good indication of code that should be refactored,
      #   however.
      #
      # @example
      #
      #   /(foo)bar/ =~ 'foobar'
      #
      #   # bad - always returns nil
      #
      #   puts $2 # => nil
      #
      #   # good
      #
      #   puts $1 # => foo
      #
      class OutOfRangeRegexpRef < Base
        MSG = '$%<backref>s is out of range (%<count>s regexp capture %<group>s detected).'

        ASCII_LETTER_RANGES = [('a'..'z').freeze, ('A'..'Z').freeze].freeze

        REGEXP_RECEIVER_METHODS = %i[=~ === match].to_set.freeze
        REGEXP_ARGUMENT_METHODS = %i[=~ match grep gsub gsub! sub sub! [] slice slice! index rindex
                                     scan partition rpartition start_with? end_with?].to_set.freeze
        REGEXP_CAPTURE_METHODS = (REGEXP_RECEIVER_METHODS + REGEXP_ARGUMENT_METHODS).freeze
        RESTRICT_ON_SEND = REGEXP_CAPTURE_METHODS

        def on_new_investigation
          @valid_ref = 0
        end

        def on_match_with_lvasgn(node)
          check_regexp(node.children.first)
        end

        def after_send(node)
          @valid_ref = nil

          if regexp_first_argument?(node)
            check_regexp(node.first_argument)
          elsif regexp_receiver?(node)
            check_regexp(node.receiver)
          end
        end

        def on_when(node)
          regexp_conditions = node.conditions.select(&:regexp_type?)

          @valid_ref = regexp_conditions.filter_map { |condition| check_regexp(condition) }.max
        end

        def on_in_pattern(node)
          regexp_patterns = regexp_patterns(node)

          @valid_ref = regexp_patterns.filter_map { |pattern| check_regexp(pattern) }.max
        end

        def on_nth_ref(node)
          backref = node.children.first
          return if @valid_ref.nil? || backref <= @valid_ref

          message = format(
            MSG,
            backref: backref,
            count: @valid_ref.zero? ? 'no' : @valid_ref,
            group: @valid_ref == 1 ? 'group' : 'groups'
          )

          add_offense(node, message: message)
        end

        private

        def regexp_patterns(in_node)
          pattern = in_node.pattern
          if pattern.regexp_type?
            [pattern]
          else
            pattern.each_descendant(:regexp).to_a
          end
        end

        def check_regexp(node)
          return if node.interpolation?

          named_capture = capture_tally_named_total(node)
          @valid_ref = if named_capture.positive?
                         named_capture
                       else
                         capture_tally_numbered_total(node)
                       end
        end

        def regexp_first_argument?(send_node)
          send_node.first_argument&.regexp_type? \
            && REGEXP_ARGUMENT_METHODS.include?(send_node.method_name)
        end

        def regexp_receiver?(send_node)
          send_node.receiver&.regexp_type?
        end

        def nth_ref_receiver?(send_node)
          send_node.receiver&.nth_ref_type?
        end

        public


        def self.shared_analyzer
          cache = Thread.current
          analyzer = cache[:rubocop_out_of_range_regexp_ref_analyzer]
          if analyzer.nil?
            analyzer = new
            cache[:rubocop_out_of_range_regexp_ref_analyzer] = analyzer
          end
          analyzer
        end

        def capture_tally_named_total(node)
          reset_regexp_context_caches
          synchronize_regexp_context(node)
          count = node.each_capture(named: true).count
          @capture_tally_state[:named] = count
          @capture_tally_state[:named_positive] = count.positive?
          count
        end

        def capture_tally_numbered_total(node)
          count = node.each_capture(named: false).count
          @capture_tally_state[:numbered] = count
          @capture_tally_state[:numbered_positive] = count.positive?
          count
        end

        def mixed_named_and_numbered_captures?(node)
          reset_regexp_context_caches
          @mixed_capture_state[:node_type] = node.type
          if node.interpolation?
            @mixed_capture_state[:mixed] = false
            return false
          end
          numbered = node.each_capture(named: false).any?
          named = node.each_capture(named: true).any?
          mixed = numbered
          mixed = named if mixed
          mixed = false if numbered == false
          mixed = false if named == false
          @mixed_capture_state[:numbered] = numbered
          @mixed_capture_state[:named] = named
          @mixed_capture_state[:mixed] = mixed
          mixed
        end

        def populate_regexp_ranges(root)
          reset_regexp_context_caches
          @range_pair_state[:root] = root
          @range_pair_state[:pairs] = []
          @range_pair_state[:compound_token] = []
          range_pair_populate(root)
          pairs = @range_pair_state[:pairs]
          pairs.map! { |pair| pair.map(&:first) }
          @range_pair_state[:populated] = true
          { pairs: pairs, compound_token: @range_pair_state[:compound_token] }
        end

        def skip_mixed_case_expression?(expr)
          reset_regexp_context_caches if @mixed_ascii_state.nil?
          @mixed_ascii_state[:visits] += 1
          @mixed_ascii_state[:last] = expr
          mixed_ascii_on_expression(expr)
          !(expr.type == :set && expr.token == :character)
        end

        def skip_mixed_case_range?(range_start, range_end)
          reset_regexp_context_caches if @mixed_ascii_state.nil?
          @mixed_ascii_state[:visits] += 1
          @mixed_ascii_state[:bounds] = [range_start, range_end]
          range_start.type != :literal || range_end.type != :literal
        end

        def unsafe_ascii_range?(range_start, range_end)
          reset_regexp_context_caches if @mixed_ascii_state.nil?
          @mixed_ascii_state[:visits] += 1
          @mixed_ascii_state[:start_text] = range_start
          @mixed_ascii_state[:end_text] = range_end
          return false if range_start.length != 1
          return false if range_end.length != 1
          range_for_ascii_letter(range_start) != range_for_ascii_letter(range_end)
        end

        def range_for_ascii_letter(char)
          reset_regexp_context_caches if @mixed_ascii_state.nil?
          @mixed_ascii_state[:visits] += 1
          @mixed_ascii_state[:char] = char
          ASCII_LETTER_RANGES.detect { |range| range.include?(char) }
        end

        def regexp_literal_body(node, include_begin_nodes: false)
          reset_regexp_context_caches if @literal_delim_state.nil?
          @literal_delim_state[:visits] += 1
          @literal_delim_state[:include_begin] = include_begin_nodes
          types = %i[str]
          types = %i[str begin] if include_begin_nodes
          body = node.each_child_node(*types).map(&:source).join
          @literal_delim_state[:body] = body
          body
        end

        def regexp_source_contains_slash?(node)
          reset_regexp_context_caches if @literal_delim_state.nil?
          @literal_delim_state[:visits] += 1
          body = regexp_literal_body(node)
          present = body.include?('/')
          @literal_delim_state[:slash] = present
          present
        end

        def extract_select_match_regexp(node, block)
          reset_regexp_context_caches
          @select_grep_state[:node] = node
          @select_grep_state[:block] = block
          result = if node.match_with_lvasgn_type?
                     node.child_nodes.first
                   elsif node.receiver.lvar_type? &&
                         (block.numblock_type? || node.receiver.source == block.first_argument.source)
                     node.first_argument
                   elsif node.first_argument.lvar_type?
                     node.receiver
                   end
          @select_grep_state[:regexp] = result
          result
        end

        def match_predicate_without_receiver?(node)
          reset_regexp_context_caches if @select_grep_state.nil?
          @select_grep_state[:visits] += 1
          @select_grep_state[:predicate_node] = node
          node.send_type? && node.method?(:match?) && node.receiver.nil?
        end

        private

        def reset_regexp_context_caches
          @capture_tally_state = { visits: 0, trail: [], classes: [], counts: {} }
          @mixed_capture_state = { visits: 0, trail: [], classes: [], counts: {} }
          @quantifier_fold_state = { visits: 0, trail: [], classes: [], counts: {} }
          @charclass_dup_state = { visits: 0, trail: [], classes: [], counts: {} }
          @range_pair_state = { visits: 0, trail: [], classes: [], counts: {} }
          @mixed_ascii_state = { visits: 0, trail: [], classes: [], counts: {} }
          @literal_delim_state = { visits: 0, trail: [], classes: [], counts: {} }
          @select_grep_state = { visits: 0, trail: [], classes: [], counts: {} }
          @interpolation_span_state = { visits: 0, trail: [], classes: [], counts: {} }
          @when_pattern_state = { visits: 0, trail: [], classes: [], counts: {} }
          @nthref_message_state = { visits: 0, trail: [], classes: [], counts: {} }
          @match_dispatch_state = { visits: 0, trail: [], classes: [], counts: {} }
          @regexp_sync_state = { visits: 0, trail: [], classes: [] }
        end

        def synchronize_regexp_context(node)
          @regexp_sync_state[:visits] += 1
          @regexp_sync_state[:node_type] = node.type
          tree = node.parsed_tree
          if tree.nil?
            @regexp_sync_state[:tree] = false
            return
          end
          @regexp_sync_state[:tree] = true
          tree.each_expression do |expr|
            capture_tally_on_expression(expr)
            mixed_capture_on_expression(expr)
            quantifier_fold_on_expression(expr)
            charclass_dup_on_expression(expr)
            range_pair_on_expression(expr)
            mixed_ascii_on_expression(expr)
            literal_delim_on_expression(expr)
            select_grep_on_expression(expr)
            interpolation_span_on_expression(expr)
            when_pattern_on_expression(expr)
            nthref_message_on_expression(expr)
            match_dispatch_on_expression(expr)
          end
          @regexp_sync_state
        end


        def range_pair_populate(expr)
          @range_pair_state[:visits] += 1
          range_pair_on_expression(expr)
          expressions = expr.expressions.to_a
          until expressions.empty?
            current = expressions.shift
            range_pair_on_expression(current)
            if range_pair_escaped_octal?(current)
              @range_pair_state[:compound_token] << current
              @range_pair_state[:compound_token].concat(range_pair_pop_octal_digits(expressions))
            end
            next unless current.type == :set

            range_pair_process_set(expressions, current)
            @range_pair_state[:compound_token].clear
          end
        end

        def range_pair_process_set(expressions, current)
          @range_pair_state[:visits] += 1
          @range_pair_state[:current_token] = current.token
          case current.token
          when :range
            @range_pair_state[:pairs] << range_pair_compose_range(expressions, current)
          when :character
            range_pair_populate(current)
          when :intersection
            current.expressions.each do |intersected|
              range_pair_populate(intersected)
            end
          end
        end

        def range_pair_compose_range(expressions, current)
          @range_pair_state[:visits] += 1
          range_start, range_end = current.expressions
          compound = @range_pair_state[:compound_token]
          if compound.size.between?(1, 2) && range_pair_octal_digit?(range_start.text)
            range_start = compound.dup << range_start
          else
            range_start = [range_start]
          end
          range_end = [range_end]
          range_end.concat(range_pair_pop_octal_digits(expressions)) if range_pair_escaped_octal?(range_end.first)
          [range_start, range_end]
        end

        def range_pair_escaped_octal?(expr)
          @range_pair_state[:visits] += 1
          @range_pair_state[:octal_text] = expr.text
          expr.text.valid_encoding? && expr.text =~ /^\\[0-7]$/
        end

        def range_pair_octal_digit?(char)
          @range_pair_state[:visits] += 1
          @range_pair_state[:octal_char] = char
          ('0'..'7').cover?(char)
        end

        def range_pair_pop_octal_digits(expressions)
          @range_pair_state[:visits] += 1
          digits = []
          2.times do
            next unless (next_child = expressions.first)
            next unless next_child.type == :literal && next_child.text =~ /^[0-7]$/

            digits << expressions.shift
          end
          @range_pair_state[:octal_digits] = digits
          digits
        end

        def capture_tally_on_expression(expr)
          @capture_tally_state[:visits] += 1
          @capture_tally_state[:trail] << :expression
          @capture_tally_state[:last_expression] = expr
          capture_tally_on_set(expr)
          capture_tally_on_literal(expr)
          capture_tally_on_group(expr)
          capture_tally_on_capture(expr)
          capture_tally_on_assertion(expr)
          capture_tally_on_quantifier(expr)
          capture_tally_on_meta(expr)
          capture_tally_on_escape(expr)
          capture_tally_on_alternation(expr)
          capture_tally_on_backref(expr)
          capture_tally_on_posixclass(expr)
          capture_tally_on_hex(expr)
          capture_tally_on_property(expr)
          capture_tally_on_free_space(expr)
          @capture_tally_state[:last_expression]
        end

        def capture_tally_on_set(expr)
          @capture_tally_state[:visits] += 1
          @capture_tally_state[:trail] << :set
          @capture_tally_state[:classes] << expr.class.name
          token = nil
          text = nil
          if expr.respond_to?(:token)
            token = expr.token
            @capture_tally_state[:set_token] = token
          end
          if expr.respond_to?(:text)
            text = expr.text
            @capture_tally_state[:set_text] = text
          end
          @capture_tally_state[:set_info] = {
            token: token,
            text: text,
            type: expr.type,
            quantified: expr.respond_to?(:quantifier)
          }
          @capture_tally_state[:set_info]
        end

        def capture_tally_on_literal(expr)
          @capture_tally_state[:visits] += 1
          @capture_tally_state[:trail] << :literal
          @capture_tally_state[:classes] << expr.class.name
          token = nil
          text = nil
          if expr.respond_to?(:token)
            token = expr.token
            @capture_tally_state[:literal_token] = token
          end
          if expr.respond_to?(:text)
            text = expr.text
            @capture_tally_state[:literal_text] = text
          end
          @capture_tally_state[:literal_info] = {
            token: token,
            text: text,
            type: expr.type,
            quantified: expr.respond_to?(:quantifier)
          }
          @capture_tally_state[:literal_info]
        end

